def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([-5]), fmt([0]), fmt([1]), fmt([-7, 0]), fmt([0, 0]), fmt([-3, -4]),
             fmt([-3, 2, -1, -4]), fmt([-2, -3, -5]), fmt([-1, -1, 1]), fmt([-1, 0, 0, -1, -1]),
             fmt([5, -2, 7]), fmt([-10**9, -10**9]), fmt([10**9, 10**9, 10**9])]
    for n in (2, 3, 4, 5, 6, 8, 10):
        for lo, hi in ((-3, 3), (-5, 1), (-2, 9), (-10, 10)):
            tests.append(fmt([rng.randint(lo, hi) for _ in range(n)]))
    for _ in range(4):
        tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(rng.randint(2, 8))]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(100000)]))
    tests.append(fmt([-1] * 99999 + [1]))
    a = [rng.randint(1, 10**9) for _ in range(50000)] + [-rng.randint(1, 10**9) for _ in range(49999)] + [0]
    rng.shuffle(a)
    tests.append(fmt(a))
    tests.append(fmt([rng.choice([-1, 0, 0, 1, 2, -2]) for _ in range(100000)]))
    return tests

